     1	import { NextResponse } from "next/server";
     2	import type { NextRequest } from "next/server";
     3	import { SESSION_COOKIE_NAME } from "@/schemas/session";
     4	
     5	/**
     6	 * Next.js 16 renamed `middleware.ts` to `proxy.ts` and the exported function
     7	 * from `middleware` to `proxy`. Do not reintroduce the old names — Next 16
     8	 * ignores them silently and every route becomes public.
     9	 *
    10	 * This proxy only decides "is there a session cookie at all". Real
    11	 * authorization happens in the layouts and Server Actions via `can()`; a proxy
    12	 * cannot reach the database.
    13	 */
    14	
    15	const PUBLIC_PREFIXES = [
    16	  "/",
    17	  "/pricing",
    18	  "/changelog",
    19	  "/about",
    20	  "/login",
    21	  "/register",
    22	  "/reset-password",
    23	  "/invite",
    24	  "/api/health",
    25	  "/api/webhooks",
    26	];
    27	
    28	function isPublicPath(pathname: string): boolean {
    29	  return PUBLIC_PREFIXES.some(
    30	    (prefix) => pathname === prefix || pathname.startsWith(`${prefix}/`),
    31	  );
    32	}
    33	
    34	export function proxy(request: NextRequest): NextResponse {
    35	  const { pathname, search } = request.nextUrl;
    36	
    37	  if (isPublicPath(pathname)) {
    38	    return NextResponse.next();
    39	  }
    40	
    41	  const session = request.cookies.get(SESSION_COOKIE_NAME);
    42	  if (!session?.value) {
    43	    const loginUrl = new URL("/login", request.url);
    44	    loginUrl.searchParams.set("next", `${pathname}${search}`);
    45	    return NextResponse.redirect(loginUrl);
    46	  }
    47	
    48	  const response = NextResponse.next();
    49	  response.headers.set("x-taskflow-authenticated", "1");
    50	  return response;
    51	}
