     6	import { cookies } from "next/headers";
     7	import { SESSION_COOKIE_NAME } from "@/schemas/session";
     8	import { resolveSession } from "@/server/services/session-service";
     9	import type { IsoTimestamp } from "@/types/common";
    10	import type { SessionPrincipal } from "@/types/member";
    11	import { parseIso } from "./date";
    12	
    13	export async function getSessionToken(): Promise<string | null> {
    14	  const jar = await cookies();
    15	  return jar.get(SESSION_COOKIE_NAME)?.value ?? null;
    16	}
    17	
    18	/**
    19	 * The signed-in principal, or `null` when there is no cookie, the token is
    20	 * unknown, or the session has expired. Callers that need a hard failure use
    21	 * `getActor()` in `@/lib/actor` instead.
    22	 */
    23	export async function getSessionPrincipal(): Promise<SessionPrincipal | null> {
    24	  const token = await getSessionToken();
    25	  if (token === null) return null;
    26	
    27	  const principal = await resolveSession(token);
    28	  if (principal === null) return null;
    29	
    30	  return parseIso(principal.expiresAt).getTime() > Date.now() ? principal : null;
    31	}
    32	
    33	export async function setSessionCookie(
    34	  token: string,
    35	  expiresAt: IsoTimestamp,
    36	): Promise<void> {
    37	  const jar = await cookies();
    38	  jar.set(SESSION_COOKIE_NAME, token, {
    39	    httpOnly: true,
    40	    sameSite: "lax",
    41	    secure: process.env.NODE_ENV === "production",
    42	    path: "/",
    43	    expires: parseIso(expiresAt),
    44	  });
    45	}
    46	
    47	export async function clearSessionCookie(): Promise<void> {
    48	  const jar = await cookies();
    49	  jar.delete(SESSION_COOKIE_NAME);
