     1	/**
     2	 * Wrapper shared by every Server Action: parses with a Zod schema, resolves the
     3	 * `Actor`, maps thrown domain errors to an `AppErrorShape` and revalidates the
     4	 * affected tags.
     5	 *
     6	 * Owner D. Every mutation in `src/actions/**` funnels through here so the four
     7	 * things each one must do — validate, authenticate, translate errors,
     8	 * revalidate — happen in exactly one place.
     9	 *
    10	 * Must call (do not reimplement): getActor, toActionResult, revalidateTagged
    11	 */
    12	
    13	import { getActor, requireActorFor } from "@/lib/actor";
    14	import { CACHE_PROFILES, revalidateTagged } from "@/lib/cache";
    15	import { toActionResult } from "@/lib/errors";
    16	import { getSessionPrincipal } from "@/lib/session";
    17	import type { ActionResult } from "@/types/api";
    18	import type { OrgId } from "@/types/common";
    19	import type { Actor } from "@/types/member";
    20	import type { ZodType } from "zod";
    21	import { UnauthorizedActionError } from "./action-errors";
    22	
    23	/** The body of an action: already-validated input plus the resolved principal. */
    24	export type ActionHandler = (input: unknown, actor: Actor) => Promise<unknown>;
    25	
    26	export type ActionOptions = {
    27	  /**
    28	   * When `true` (the default) the organization is taken from the parsed input —
    29	   * either an `orgSlug` or an `orgId` field. When `false` the action does not
    30	   * name an organization and the session's active org is used instead.
    31	   */
    32	  requireOrg?: boolean;
    33	  /** Static cache tags invalidated once the handler resolves. */
    34	  revalidate?: readonly string[];
    35	  /** cacheLife profile handed to `revalidateTag` — required in Next 16. */
    36	  cacheProfile?: string;
    37	};
    38	
    39	type OrgBearingInput = { orgSlug?: unknown; orgId?: unknown };
    40	
    41	/**
    42	 * Resolves the actor for one action call.
    43	 *
    44	 * `getActor(orgSlug)` is the primary path because most mutations are dispatched
    45	 * from a `[orgSlug]` route; actions whose payload carries the branded `orgId`
    46	 * instead resolve through `requireActorFor()`.
    47	 */
    48	async function resolveActorFor(input: unknown, fromInput: boolean): Promise<Actor> {
    49	  if (fromInput && typeof input === "object" && input !== null) {
    50	    const record = input as OrgBearingInput;
    51	    if (typeof record.orgSlug === "string" && record.orgSlug.length > 0) {
    52	      return getActor(record.orgSlug);
    53	    }
    54	    if (typeof record.orgId === "string" && record.orgId.length > 0) {
    55	      return requireActorFor(record.orgId as OrgId);
    56	    }
    57	  }
    58	
    59	  const principal = await getSessionPrincipal();
    60	  if (principal === null || principal.activeOrgId === null) {
    61	    throw new UnauthorizedActionError();
    62	  }
    63	  return requireActorFor(principal.activeOrgId);
    64	}
    65	
    66	/** Adds the monotonic token `useActionState` uses to tell two results apart. */
    67	function stamp<T>(result: ActionResult<T>): ActionResult<T> {
    68	  const submittedAt = new Date().toISOString();
    69	  return result.ok
    70	    ? { ok: true, data: result.data, submittedAt }
    71	    : { ok: false, error: result.error, submittedAt };
    72	}
    73	
    74	export function withAction<TSchema extends ZodType, TData>(
    75	  schema: TSchema,
    76	  handler: ActionHandler,
    77	  options: ActionOptions = {},
    78	): (raw: unknown) => Promise<ActionResult<TData>> {
    79	  return async function runAction(raw: unknown): Promise<ActionResult<TData>> {
    80	    const parsed = schema.safeParse(raw);
    81	    if (!parsed.success) {
    82	      return stamp(toActionResult(parsed.error));
    83	    }
    84	
    85	    try {
    86	      const actor = await resolveActorFor(parsed.data, options.requireOrg !== false);
    87	      const data = (await handler(parsed.data, actor)) as TData;
    88	
    89	      const tags = options.revalidate ?? [];
    90	      if (tags.length > 0) {
    91	        revalidateTagged(tags, options.cacheProfile ?? CACHE_PROFILES.minutes);
    92	      }
    93	
    94	      return stamp({ ok: true, data });
    95	    } catch (error) {
    96	      return stamp(toActionResult(error));
    97	    }
    98	  };
    99	}

